param([string]$VictimVmName='XDR-Victim-Sprint18',[string]$CredentialPath='D:\VMs\XDR-Victim-Sprint18\victim-credential.xml',[int]$TimeoutSeconds=300)
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '../..');Set-Location $root
$domains=[ordered]@{process=@('platform.process_entities','platform-processes');file=@('platform.file_entities','platform-files');registry=@('platform.registry_events','platform-registry-events');network=@('platform.network_events','platform-network-events');dns=@('platform.dns_events','platform-dns-events');module=@('platform.module_events','platform-module-events');persistence=@('platform.persistence_events','platform-persistence-events');identity=@('platform.identity_events','platform-identity-events');execution=@('platform.execution_events','platform-execution-events');detection=@('platform.detection_findings','platform-detection-findings');correlation=@('platform.correlated_findings','platform-correlated-findings')}
function Pg($table){[long]((docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) from $table;").Trim())};function Os($index){[long](((docker exec deployment-opensearch-1 curl -sf "http://localhost:9200/$index/_count")|ConvertFrom-Json).count)}
$deadline=[DateTimeOffset]::UtcNow.AddSeconds($TimeoutSeconds);do{Start-Sleep 3;$postgres=[ordered]@{};$openSearch=[ordered]@{};$differences=[ordered]@{};foreach($n in $domains.Keys){$postgres[$n]=Pg $domains[$n][0];$openSearch[$n]=Os $domains[$n][1];$differences[$n]=$postgres[$n]-$openSearch[$n]};$transport=((docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) filter(where published_at is null and failed_at is null)||'|'||count(*) filter(where failed_at is not null) from platform.outbox;").Trim()).Split('|')|ForEach-Object{[long]$_};$js=(docker exec deployment-nats-1 wget -qO- 'http://localhost:8222/jsz?streams=true&consumers=true')|ConvertFrom-Json;$consumers=@($js.account_details.stream_detail.consumer_detail);$pending=[long](($consumers|Measure-Object num_pending -Sum).Sum);$ack=[long](($consumers|Measure-Object num_ack_pending -Sum).Sum);$cred=Import-Clixml $CredentialPath;try{$s=New-PSSession -VMName $VictimVmName -Credential $cred -ErrorAction Stop;$queues=Invoke-Command -Session $s -ScriptBlock {$root='C:\Sprint19Qualification\runtime-data';$o=[ordered]@{};foreach($n in 'process','file','registry','network','dns','module','persistence','identity','execution'){$p="$root\$n-queue";$o[$n]=if(Test-Path $p){@(Get-ChildItem $p -File -Filter '*.json').Count}else{0}};[pscustomobject]$o};Remove-PSSession $s}catch{$queues=$null};$queueRemaining=if($queues){[long](($queues.psobject.Properties|Where-Object{$_.Name-notlike'PS*'-and$_.Name-ne'RunspaceId'}|ForEach-Object{[long]$_.Value}|Measure-Object -Sum).Sum)}else{1};$exact=@($differences.Values|Where-Object{$_-ne0}).Count-eq0;$drained=$transport[0]-eq0-and$transport[1]-eq0-and$pending-eq0-and$ack-eq0-and$queueRemaining-eq0}while((-not($exact-and$drained))-and[DateTimeOffset]::UtcNow-lt$deadline)
$response=((docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select (select count(*) from platform.response_actions)||'|'||(select count(*) from platform.response_action_audit)||'|'||(select coalesce(sum(jsonb_array_length(action_data->'auditHistory')),0) from platform.response_actions)||'|'||(select count(*) from platform.response_actions where state not in ('Succeeded','Failed','TimedOut','Cancelled','Expired','Rejected'));").Trim()).Split('|')|ForEach-Object{[long]$_}
$report=[ordered]@{schemaVersion='sprint19-final-reconciliation.v1';capturedAt=[DateTimeOffset]::UtcNow;postgres=$postgres;openSearch=$openSearch;differences=$differences;queues=$queues;response=@{actions=$response[0];auditRows=$response[1];snapshotAudit=$response[2];nonterminal=$response[3]};outbox=@{pending=$transport[0];failed=$transport[1]};nats=@{pending=$pending;ackPending=$ack;redelivered=[long](($consumers|Measure-Object num_redelivered -Sum).Sum)};passed=$exact-and$drained-and$response[1]-eq$response[2]-and$response[3]-eq0}
$report|ConvertTo-Json -Depth 30|Set-Content artifacts/sprint19-final-reconciliation.json -Encoding utf8;$report|ConvertTo-Json -Depth 30;if(!$report.passed){exit 1}
